import WorkloadConfig, { Stage } from "../common/interfaces/workload_config.interface";
import { DefaultThresholds } from "./treshold.config";

export const Workloads: any = {
    stag: {
        averageLow: [
            { duration: '1m', target: 50 },
            { duration: '5m', target: 50 },
            { duration: '1m', target: 0 },
        ],
        averageMed: [
            { duration: '2m', target: 250 },
            { duration: '10m', target: 250 },
            { duration: '2m', target: 0 },
        ],
        averageHigh: [
            { duration: '2m', target: 500 },
            { duration: '10m', target: 500 },
            { duration: '2m', target: 0 },
        ],
        stress: [
            { duration: '5s', target: 1000 },
            { duration: '15s', target: 1000 },
            { duration: '5s', target: 0 },
        ],
    },
    pre: {
        // Add pre-prod-specific load stages here when ready
    },
    prod: {
        // Add prod-specific load stages here when ready
    }
};

export const getWorkload = (envName: string, workloadName: string): WorkloadConfig => {
    let stages: Stage[];

    if (workloadName.toLowerCase() === 'smoke') {
        stages = Workloads.smoke;
    } else {
        const envWorkloads = Workloads[envName.toLowerCase()];
        if (envWorkloads && envWorkloads[workloadName]) {
            stages = envWorkloads[workloadName];
        } else {
            console.warn(`Workload ${workloadName} not found for env ${envName}. Falling back to smoke.`);
            stages = Workloads.smoke;
        }
    }

    return {
        scenarios: {
            [workloadName]: {
                executor: 'ramping-vus',
                stages: stages
            }
        },
        thresholds: DefaultThresholds
    };
};
